18	// fakeLoginJWT builds an unsigned JWT whose payload carries the given
19	// home_jurisdiction claim — enough for the client-side routing decisions,
20	// which never verify the signature.
21	func fakeLoginJWT(t *testing.T, homeJurisdiction string) string {
22		t.Helper()
23		payload, err := json.Marshal(map[string]string{"home_jurisdiction": homeJurisdiction})
24		if err != nil {
25			t.Fatal(err)
26		}
27		header := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"none"}`))
28		return header + "." + base64.RawURLEncoding.EncodeToString(payload) + ".sig"
29	}
