// Jurisdiction slots not on c.JurisdictionAudiences can't be found offline —
// tokenstore has no enumeration — so entries written by a CLI predating that
// bookkeeping are left to expire with their TTL.
func deleteContextKeychain(c *contexts.Context) error {
	if c == nil || c.Handle == "" {
		return nil
